import { Amplify } from 'aws-amplify';
import { uploadData, getUrl, remove, list } from 'aws-amplify/storage';

let isConfigured = false;
let activeBucketName = null;

// Clean and sanitize file names for S3 keys
function sanitizeFileName(name = 'file') {
  return name.replace(/[^a-zA-Z0-9._-]/g, '_');
}

/**
 * Initialize Amplify Storage.
 * Attempts to load generated amplify_outputs.json or falls back to VITE_AWS_* environment variables.
 */
export function initAmplifyStorage() {
  if (isConfigured) return true;

  try {
    // 1. Check if amplify_outputs.json was generated by `npx ampx sandbox` or Amplify pipeline
    let outputs = null;
    try {
      outputs = (window?.__AMPLIFY_OUTPUTS__ || null);
    } catch (_) {}

    // 2. Check environment variables (supports standard VITE_* and Vercel-friendly non-reserved names)
    const envBucket =
      import.meta.env?.VITE_STORAGE_BUCKET ||
      import.meta.env?.VITE_AMPLIFY_BUCKET ||
      import.meta.env?.VITE_AMPLIFY_STORAGE_BUCKET ||
      import.meta.env?.VITE_AWS_STORAGE_BUCKET_NAME;

    const envRegion =
      import.meta.env?.VITE_STORAGE_REGION ||
      import.meta.env?.VITE_AMPLIFY_REGION ||
      import.meta.env?.VITE_AWS_REGION ||
      'ap-south-1';

    const envUserPoolId =
      import.meta.env?.VITE_USER_POOL_ID ||
      import.meta.env?.VITE_AMPLIFY_USER_POOL_ID ||
      import.meta.env?.VITE_AWS_USER_POOLS_ID;

    const envAppClientId =
      import.meta.env?.VITE_USER_POOL_CLIENT_ID ||
      import.meta.env?.VITE_AMPLIFY_CLIENT_ID ||
      import.meta.env?.VITE_AWS_USER_POOLS_WEB_CLIENT_ID;

    if (outputs) {
      Amplify.configure(outputs);
      activeBucketName = outputs?.storage?.bucket_name || 'thoughtflows-storage';
      isConfigured = true;
      console.log('✓ AWS Amplify Storage initialized from amplify_outputs');
      return true;
    }

    if (envBucket) {
      const config = {
        Storage: {
          S3: {
            bucket: envBucket,
            region: envRegion
          }
        }
      };

      if (envUserPoolId && envAppClientId) {
        config.Auth = {
          Cognito: {
            userPoolId: envUserPoolId,
            userPoolClientId: envAppClientId
          }
        };
      }

      Amplify.configure(config);
      activeBucketName = envBucket;
      isConfigured = true;
      console.log(`✓ AWS Amplify Storage initialized with bucket: ${envBucket} (${envRegion})`);
      return true;
    }

    return false;
  } catch (err) {
    console.warn('Amplify Storage initialization notice:', err.message);
    return false;
  }
}

// Auto-run initialization on module import
initAmplifyStorage();

/**
 * Check if Amplify Storage is configured and ready to accept uploads
 */
export function isAmplifyStorageConfigured() {
  if (isConfigured) return true;
  return initAmplifyStorage();
}

/**
 * Get the currently active S3 bucket name if configured
 */
export function getActiveBucketName() {
  return activeBucketName;
}

/**
 * Upload a Training Material file to AWS Amplify Storage
 * Path: training-materials/{category}/{timestamp}-{filename}
 */
export async function uploadTrainingMaterialFile(file, options = {}) {
  const { category = 'general', onProgress } = options;
  const cleanCategory = String(category).toLowerCase().replace(/[^a-z0-9_-]/g, '_');
  const cleanName = sanitizeFileName(file.name);
  const storagePath = `training-materials/${cleanCategory}/${Date.now()}-${cleanName}`;

  const task = uploadData({
    path: storagePath,
    data: file,
    options: {
      contentType: file.type || 'application/octet-stream',
      onProgress: (progress) => {
        if (onProgress && progress.totalBytes) {
          const pct = Math.round((progress.transferredBytes / progress.totalBytes) * 100);
          onProgress({ transferred: progress.transferredBytes, total: progress.totalBytes, percent: pct });
        }
      }
    }
  });

  const result = await task.result;
  const urlResult = await getUrl({ path: storagePath });

  return {
    storageKey: storagePath,
    storageUrl: urlResult.url.toString(),
    path: result.path || storagePath,
    fileName: file.name,
    fileSize: file.size,
    mimeType: file.type || 'application/octet-stream',
    storageProvider: 'amplify'
  };
}

