/**
 * Get a presigned download / stream URL for a file stored in Amplify Storage
 */
export async function getStorageFileUrl(storageKey, options = {}) {
  if (!storageKey) return null;
  // If already a full URL (CDN/CloudFront/Presigned), return it directly
  if (storageKey.startsWith('http://') || storageKey.startsWith('https://')) {
    return storageKey;
  }

  try {
    const res = await getUrl({
      path: storageKey,
      options: {
        expiresIn: options.expiresIn || 3600, // 1 hour default expiration
        validateObjectExistence: options.validateObjectExistence ?? false
      }
    });
    return res.url.toString();
  } catch (err) {
    console.error('Failed to get Amplify storage URL for:', storageKey, err);
    return null;
  }
}

/**
 * Delete a file from Amplify S3 Storage
 */
export async function removeStorageFile(storageKey) {
  if (!storageKey) return;
  try {
    await remove({ path: storageKey });
    return true;
  } catch (err) {
    console.error('Failed to delete file from Amplify Storage:', storageKey, err);
    throw err;
  }
}

/**
 * List files in an Amplify Storage path prefix
 */
export async function listStorageFiles(pathPrefix = '') {
  try {
    const res = await list({
      path: pathPrefix,
      options: {
        listAll: true
      }
    });
    return res.items || [];
  } catch (err) {
    console.error('Failed to list files in Amplify Storage path:', pathPrefix, err);
    return [];
  }
}

export default {
  initAmplifyStorage,
  isAmplifyStorageConfigured,
  getActiveBucketName,
  uploadTrainingMaterialFile,
  uploadStudentSubmissionFile,
  uploadResumeFile,
  uploadRecordingFile,
  getStorageFileUrl,
  removeStorageFile,
  listStorageFiles
};
